def find_longest_self_contained_substring(s):
    n = len(s)
    first = {}
    last = {}
    for i, c in enumerate(s):
        if c not in first:
            first[c] = i
        last[c] = i

    max_len = -1
    for l in range(n):
        # a valid substring must start at the first occurrence of its first character
        if first[s[l]] != l:
            continue
        right = l
        for i in range(l, n):
            c = s[i]
            if first[c] < l:  # c also occurs before l, so no longer window is valid
                break
            right = max(right, last[c])
            # all characters in s[l..i] have all their occurrences inside it
            if i == right and i - l + 1 < n:
                max_len = max(max_len, i - l + 1)
    return max_len
